{
  "name": "sentience-loop",
  "version": "1.0.0",
  "description": "A metacognitive loop that perceives signals, makes falsifiable predictions, scores them when they mature, learns from the surprises, and keeps an honest audit trail — so an agent measures its own accuracy instead of asserting it.",
  "license": "MIT",
  "type": "commonjs",
  "scripts": {
    "test": "node examples/demo.cjs >/dev/null && echo ok",
    "check": "node --check lib/sentience-loop.cjs && node --check examples/demo.cjs && node --check examples/sensors.example.cjs && echo ok"
  },
  "keywords": [
    "predictive-processing",
    "metacognition",
    "self-monitoring",
    "calibration",
    "surprise-minimization",
    "cognitive-architecture",
    "zero-dependencies"
  ],
  "engines": {
    "node": ">=18"
  },
  "dependencies": {},
  "devDependencies": {},
  "bin": {
    "sentience-loop": "lib/sentience-loop.cjs"
  }
}
